ty_points_per_reward']??100)?>"><label class="form-label mt-2">Valeur récompense USD</label><input class="form-control" name="loyalty_reward_usd" type="number" step="0.01" value="<?=e($settings['loyalty_reward_usd']??1)?>"><hr><h5>Analytics</h5><label class="form-label">Seuil couverture faible (jours)</label><input class="form-control" name="low_stock_days_threshold" type="number" value="<?=e($settings['low_stock_days_threshold']??5)?>"><label class="form-label mt-2">Produit dormant après (jours)</label><input class="form-control" name="dormant_days" type="number" value="<?=e($settings['dormant_days']??30)?>"></div></div></div><button class="btn btn-km btn-lg mt-3">Enregistrer les paramètres</button></form><div class="row g-3 mt-2"><div class="col-lg-5"><div class="km-card p-3"><h5>Ajouter une zone de livraison</h5><form method="post" action="<?=e(base_url('settings/delivery-zones'))?>"><?=csrf_field()?><div class="row g-2"><div class="col-7"><input class="form-control" name="name" placeholder="Zone / commune" required></div><div class="col-5"><input class="form-control" type="number" step="0.01" min="0" name="fee_usd" placeholder="Frais FC" required></div></div><button class="btn btn-dark mt-2">Ajouter</button></form></div></div><div class="col-lg-7"><div class="km-card p-3"><h5>Zones configurées</h5><table class="table"><thead><tr><th>Zone</th><th>Frais FC</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($zones as $z):?><tr><td><?=e($z['name'])?></td><td colspan="3"><form method="post" action="<?=e(base_url('settings/delivery-zones/'.$z['id']))?>" class="d-flex gap-2"><?=csrf_field()?><input class="form-control form-control-sm" style="max-width:120px" type="number" step="0.01" name="fee_usd" value="<?=e($z['fee_usd'])?>"><select class="form-select form-select-sm" style="max-width:130px" name="status"><option <?=selected($z['status'],'ACTIVE')?>>ACTIVE</option><option <?=selected($z['status'],'INACTIVE')?>>INACTIVE</option></select><button class="btn b